function photoFigure(photo,lang,caption=true){if(!photo)return '';const alt=T('Vista de '+photo.name+' en Búzios','Vista de '+photo.name+' em Búzios','View of '+photo.name+' in Búzios')[lang];const credits=photo.artist&&photo.source&&photo.licenseUrl&&photo.license?` · <a href="${esc(photo.source)}" target="_blank" rel="noopener noreferrer">${esc(photo.artist)}</a> · <a href="${esc(photo.licenseUrl)}" target="_blank" rel="license noopener noreferrer">${esc(photo.license)}</a>`:'';return `<figure class="bz-card-photo"><img src="${esc(photo.src)}" alt="${esc(alt)}" width="${photo.width}" height="${photo.height}" loading="lazy" decoding="async">${caption?`<figcaption>${esc(photo.name)}${credits}</figcaption>`:''}</figure>`;}

function value(v,lang){return v&&typeof v==='object'&&!Array.isArray(v)&&('ES' in v)?v[lang]:v;}
function esc(s=''){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));}
function localizedHref(href,lang){if(!href||/^(?:https?:|mailto:|tel:|#)/.test(href))return href;const clean=href.replace(/^\/(?:pt|en)(?=\/)/,'');return lang==='ES'?clean:'/'+lang.toLowerCase()+clean;}
function shortCopy(text,max=152){const clean=String(text||'').trim();const first=clean.split(/(?<=[.!?])\s+/)[0]||clean;if(first.length<=max)return first;return first.slice(0,max-1).replace(/\s+\S*$/,'')+'…';}
function whatsapp(text){return 'https://wa.me/5521969946938?text='+encodeURIComponent(text);}
function editorialDetails(it,lang){
 const detail=it.details?`<dl class="bz-editorial-details">${it.details.map(d=>`<dt>${esc(value(d.title,lang))}</dt><dd>${esc(value(d.text,lang))}</dd>`).join('')}</dl>`:'';
 const actions=it.actions?.length?`<div class="bz-editorial-actions">${it.actions.map(a=>{const href=a.href||'';const external=/^https?:/.test(href);return `<a href="${esc(href)}"${external?' target="_blank" rel="noopener noreferrer"':''}>${esc(value(a.label,lang))} →</a>`;}).join('')}</div>`:'';
 const slot='';
 return detail+actions+slot;
}
function editorialMatrix(matrix,lang){if(!matrix)return '';const copy={ES:{profile:'Perfil y playa cercana',more:'Ver los 18 criterios',all:'12 zonas · 18 dimensiones'},PT:{profile:'Perfil e praia próxima',more:'Ver os 18 critérios',all:'12 regiões · 18 dimensões'},EN:{profile:'Best fit and nearby beach',more:'See all 18 criteria',all:'12 areas · 18 dimensions'}}[lang];return `<div class="bz-zone-atlas" aria-label="${esc(copy.all)}">${matrix.rows.map(([name,cells],i)=>`<article class="bz-zone-card"><span class="bz-card-number">${String(i+1).padStart(2,'0')}</span><h3>${esc(name)}</h3><p class="bz-zone-label">${esc(copy.profile)}</p><p>${esc(shortCopy(value(cells[0],lang),138))}</p><details><summary>${esc(copy.more)}</summary><dl>${matrix.columns.map((column,j)=>`<dt>${esc(value(column,lang))}</dt><dd>${esc(value(cells[j],lang))}</dd>`).join('')}</dl></details></article>`).join('')}</div>`;}
function renderAreaIndex(s,lang){
 const intro={ES:{kicker:'A TU RITMO',title:'Explora barrio por barrio',lead:'Abre una zona para entender qué ofrece, qué logística conviene revisar y cómo elegir una base que funcione para tu viaje.',action:'ABRIR PERFIL DE ZONA',credit:'Foto'},PT:{kicker:'NO SEU RITMO',title:'Explore bairro por bairro',lead:'Abra uma região para entender o que ela oferece, qual logística conferir e como escolher uma base que funcione para sua viagem.',action:'ABRIR PERFIL DA REGIÃO',credit:'Foto'},EN:{kicker:'AT YOUR OWN PACE',title:'Explore Búzios area by area',lead:'Open an area to understand what it offers, which logistics to check and how to choose a base that works for your trip.',action:'OPEN AREA PROFILE',credit:'Photo'}}[lang];
 return `<section class="editorial bh-individual-index bz-area-index"><div class="section-head"><p class="kicker">${intro.kicker}</p><h2>${intro.title}</h2><p>${intro.lead}</p></div><div class="topic-grid bz-area-topic-grid">${(s.items||[]).map((it,i)=>{const mapped=areaProfilePhotos[value(it.title,'ES')],photo=(typeof mapped==='string'?buziosPhotos[mapped]:mapped)||buziosPhotos['Paisaje de Búzios'];const name=value(it.title,lang),text=value(it.text,lang),credit=photo.source&&photo.artist&&photo.license?`<small class="bz-area-credit">${intro.credit}: ${esc(photo.name)} · <a href="${esc(photo.source)}" target="_blank" rel="noopener noreferrer">${esc(photo.artist)}</a> · <a href="${esc(photo.licenseUrl)}" target="_blank" rel="license noopener noreferrer">${esc(photo.license)}</a></small>`:'';return `<article class="topic bz-area-topic"><img class="bh-topic-mini" src="${esc(photo.src)}" alt="${esc(T('Vista de '+photo.name+' en Búzios','Vista de '+photo.name+' em Búzios','View of '+photo.name+' in Búzios')[lang])}" width="${photo.width}" height="${photo.height}" loading="lazy" decoding="async"><b>${esc(name)}</b><details><summary>${intro.action} →</summary><p>${esc(text)}</p></details>${credit}</article>`}).join('')}</div></section>`;
}
