function renderExperienceIndex(page,lang){
 const labels={ES:{kicker:'SALIDAS DESDE BÚZIOS',groups:['MAR Y TIERRA','EXCURSIONES REGIONALES'],status:'CONSULTAR',open:'ABRIR FICHA',local:'OPCIONES LOCALES',regional:'SALIDAS REGIONALES'},PT:{kicker:'SAÍDAS DE BÚZIOS',groups:['MAR E TERRA','PASSEIOS REGIONAIS'],status:'CONSULTAR',open:'ABRIR GUIA',local:'OPÇÕES LOCAIS',regional:'SAÍDAS REGIONAIS'},EN:{kicker:'DEPARTURES FROM BÚZIOS',groups:['SEA AND LAND','REGIONAL EXCURSIONS'],status:'ENQUIRE',open:'OPEN GUIDE',local:'LOCAL OPTIONS',regional:'REGIONAL DEPARTURES'}}[lang];
 const groups=page.sections.slice(0,2);
 return `<section class="editorial experiences-catalog bz-experiences-catalog"><div class="section-head"><p class="kicker">${labels.kicker}</p><h1>${esc(value(page.title,lang))}</h1><p>${esc(value(page.description,lang))}</p><p>${esc(value(page.intro,lang))}</p></div>${groups.map((s,si)=>`<div class="exp-group"><div class="exp-group-head"><h2>${esc(value(s.title,lang))}</h2><small>${si===0?labels.local:labels.regional}</small></div><div class="exp-grid">${s.items.map(it=>{const name=value(it.title,lang),copy=value(it.text,lang),photo=experienceCardPhotos[value(it.title,'ES')],href=localizedHref(it.href,lang);const caption=photo?.credit?`<span class="exp-photo-credit">${esc(photo.credit.name)} · ${esc(photo.credit.artist)} · ${esc(photo.credit.license)}</span>`:'';return `<a class="exp-card" href="${esc(href)}"><div class="exp-photo"><img src="${esc(photo.src)}" alt="${esc(value(photo.alt,lang))}" width="1200" height="750" loading="lazy" decoding="async"><span class="exp-price">${labels.status}</span></div><div class="exp-info"><h3>${esc(name)}</h3><p>${esc(shortCopy(copy,190))}</p>${caption}<span class="meta">${labels.open} →</span></div></a>`}).join('')}</div></div>`).join('')}</section>`;
}
function renderBuziosFullDay(page,lang,whatsappHref){
 const copy={
  back:T('← Volver a Tours','← Voltar aos passeios','← Back to Tours')[lang],
  badge:T('★ Experiencia destacada','★ Experiência em destaque','★ Featured experience')[lang],
  eyebrow:T('Experiencia local de día completo','Experiência local de dia inteiro','Local full-day experience')[lang],
  headline:T('Mar, paseo y logística en Búzios','Mar, passeio e logística em Búzios','Sea, sightseeing and logistics in Búzios')[lang],
  price:T('Consultar','Consultar','Enquire')[lang],
  per:T('valor y condiciones para tu fecha','valor e condições para sua data','price and terms for your date')[lang],
  sea:T('Paseo en barco','Passeio de barco','Boat trip')[lang],
  land:T('Panorama terrestre','Panorama terrestre','Land overview')[lang],
  meal:T('Pausa para almorzar','Pausa para almoço','Lunch break')[lang],
  confirmed:T('Un día combinado, pendiente de confirmar','Um dia combinado, sujeito a confirmação','A combined day, subject to confirmation')[lang],
  components:T('Componentes de la jornada','Componentes do dia','Day components')[lang],
  what:T('Todo lo que debes saber antes de reservar','Tudo o que você precisa saber antes de reservar','What to know before you book')[lang],
  ask:T('Antes de reservar','Antes de reservar','Before booking')[lang],
  askCopy:value(page.pending,lang),
  final:T('Consulta el Full Day Búzios','Consulte o Full Day Búzios','Ask about Full Day Búzios')[lang],
  finalCopy:T('Cuéntame tu fecha, dónde te alojas y cuántas personas viajan. Yo confirmaré contigo el recorrido, los componentes y el valor vigente antes de que decidas.','Conte a data, onde ficará hospedado e quantas pessoas viajam. Vou confirmar o roteiro, os componentes e o valor vigente antes de você decidir.','Tell me your date, where you are staying and how many people are travelling. I will confirm the route, components and current price before you decide.')[lang],
  cta:T('CONSULTAR POR WHATSAPP','CONSULTAR PELO WHATSAPP','ASK ON WHATSAPP')[lang],
  bookingTitle:T('Reserva tu Full Day Búzios','Consulte seu Full Day Búzios','Enquire about Full Day Búzios')[lang],
  bookingEyebrow:T('RESERVA CON ERNESTINHO','RESERVA COM ERNESTINHO','ENQUIRE WITH ERNESTINHO')[lang],
  bookingIntro:T('Cuéntame cómo es tu viaje. Yo reviso la disponibilidad y te respondo con las condiciones vigentes para tu fecha. Enviar este formulario abre una consulta por WhatsApp; no confirma ni cobra una reserva.','Conte como será sua viagem. Vou verificar a disponibilidade e responder com as condições vigentes para sua data. O formulário abre uma consulta pelo WhatsApp; não confirma nem cobra uma reserva.','Tell me about your trip. I will check availability and reply with the current terms for your date. This form opens a WhatsApp enquiry; it does not confirm or charge a booking.')[lang],
  send:T('ENVIAR MI SOLICITUD POR WHATSAPP','ENVIAR MINHA SOLICITAÇÃO PELO WHATSAPP','SEND MY WHATSAPP ENQUIRY')[lang],
  footnote:T('La consulta no confirma la salida. Espera mi respuesta con disponibilidad, valor e inclusiones antes de pagar.','A consulta não confirma a saída. Aguarde minha resposta com disponibilidade, valor e inclusões antes de pagar.','The enquiry does not confirm a departure. Wait for my reply with availability, price and inclusions before paying.')[lang]
 };
 const imgRows=[
  {photo:buziosPhotos['Armação'],tag:T('01 · EXPERIENCIA DE MAR','01 · EXPERIÊNCIA NO MAR','01 · SEA EXPERIENCE')[lang],title:copy.sea,text:T('La ficha histórica menciona una salida en escuna. Confirma con el operador el embarque, la duración, las tasas, el itinerario y las condiciones de mar para tu fecha.','A ficha histórica menciona uma saída de escuna. Confirme com o operador o embarque, a duração, as taxas, o roteiro e as condições do mar para sua data.','The historical listing mentions a schooner outing. Confirm the meeting point, duration, fees, route and sea conditions with the operator for your date.')[lang]},
  {photo:buziosPhotos['Orla Bardot'],tag:T('02 · RECORRIDO TERRESTRE','02 · PASSEIO TERRESTRE','02 · LAND TOUR')[lang],title:copy.land,text:T('La propuesta también ha mencionado una jardinera panorámica. Pregunta qué playas o miradores incluye hoy y en qué orden se realizan las paradas.','A proposta também mencionou uma jardineira panorâmica. Pergunte quais praias ou mirantes estão incluídos hoje e em que ordem acontecem as paradas.','The proposal has also mentioned an open panoramic vehicle. Ask which beaches or viewpoints are included now and the order of the stops.')[lang]},
  {photo:buziosPhotos['Porto da Barra'],tag:T('03 · COMPONENTE GASTRONÓMICO','03 · COMPONENTE GASTRONÔMICO','03 · FOOD COMPONENT')[lang],title:copy.meal,text:T('El almuerzo aparece en la composición histórica, pero no lo doy por incluido hasta confirmarlo. Pregunta por el lugar, el menú, las bebidas, las restricciones alimentarias y cualquier coste adicional.','O almoço aparece na composição histórica, mas não considero incluído até confirmar. Pergunte pelo local, cardápio, bebidas, restrições alimentares e qualquer custo adicional.','Lunch appears in the historical package, but I do not treat it as included until confirmed. Ask about the venue, menu, drinks, dietary restrictions and any extra charge.')[lang]}
 ];
 const rowHtml=imgRows.map((r,i)=>`<article class="stop"><div class="photo"><img src="${esc(r.photo.src)}" alt="${esc(T('Paisaje de '+r.photo.name+' en Búzios','Paisagem de '+r.photo.name+' em Búzios','View of '+r.photo.name+' in Búzios')[lang])}" width="${r.photo.width}" height="${r.photo.height}" loading="lazy" decoding="async"></div><div><span class="fd-eyebrow">${esc(r.tag)}</span><h3>${esc(r.title)}</h3><p>${esc(r.text)}</p></div></article>`).join('');
 const questions=[
  [T('¿Qué está incluido?','O que está incluído?','What is included?')[lang],T('Solicita por escrito cada componente vigente: traslado, escuna, almuerzo y jardinera. La combinación histórica no garantiza inclusión actual.','Peça por escrito cada componente vigente: traslado, escuna, almoço e jardineira. A combinação histórica não garante inclusão atual.','Ask in writing which components are currently included: transfer, schooner, lunch and panoramic vehicle. The historical package does not guarantee current inclusions.')[lang]],
  [T('¿Dónde empieza y termina?','Onde começa e termina?','Where does it start and finish?')[lang],T('La salida se organiza desde Búzios. Confirma punto de encuentro, zona de recogida y hora de regreso antes de reservar.','A saída é organizada em Búzios. Confirme ponto de encontro, área de embarque e horário de retorno antes de reservar.','The outing is arranged from Búzios. Confirm the meeting point, pick-up area and return time before booking.')[lang]],
  [T('¿Cuánto dura?','Quanto tempo dura?','How long does it take?')[lang],T('La duración y el orden del recorrido dependen de la operación confirmada para ese día.','A duração e a ordem do roteiro dependem da operação confirmada para o dia.','Duration and route order depend on the operation confirmed for that day.')[lang]],
  [T('¿Qué pasa con el mar o el clima?','E se o mar ou o clima mudar?','What if the sea or weather changes?')[lang],T('Pregunta qué tramo se modifica, cómo se informa la decisión y cuáles son las condiciones de cambio o cancelación.','Pergunte qual etapa muda, como a decisão será comunicada e quais são as condições para alteração ou cancelamento.','Ask which part may change, how the decision is communicated and what the change or cancellation terms are.')[lang]],
  [T('¿Hay tasas o bebidas aparte?','Há taxas ou bebidas à parte?','Are fees or drinks extra?')[lang],T('Pide el desglose del valor final por persona y confirma tasas, bebidas y consumos que no estén expresamente incluidos.','Peça o detalhamento do valor final por pessoa e confirme taxas, bebidas e consumos que não estejam expressamente incluídos.','Ask for the final per-person breakdown and confirm fees, drinks and spending not explicitly included.')[lang]],
  [T('¿Puedo viajar con niños?','Posso ir com crianças?','Can children join?')[lang],T('Confirma edades aceptadas, condiciones de seguridad, chalecos, asientos y cualquier requisito específico con el operador.','Confirme idades aceitas, condições de segurança, coletes, assentos e qualquer requisito específico com o operador.','Confirm accepted ages, safety terms, life jackets, seating and any specific requirements with the operator.')[lang]]
 ];
 const photo=page.hero||buziosPhotos['Paisaje de Búzios'].src;
 return `<section class="fd"><div class="fd-wrap"><a class="fd-back" href="${esc(localizedHref('/destinos/buzios/experiencias/',lang))}">${copy.back}</a><header class="fd-head"><span class="fd-badge">${copy.badge}</span><h1>Full Day <span>Búzios</span></h1><p>${esc(value(page.description,lang))}</p></header><div class="video"><img src="${esc(photo)}" alt="${esc(T('Costa de Búzios para una jornada de mar y tierra','Litoral de Búzios para um dia de mar e terra','Búzios coast for a day of sea and land')[lang])}" width="1600" height="900" fetchpriority="high" decoding="async"></div><section class="fd-card"><div class="fd-intro"><div><span class="fd-eyebrow">${copy.eyebrow}</span><h2>${copy.headline}</h2><p>${esc(value(page.intro,lang))}</p><p>${esc(value(page.confirmed,lang))}</p></div><div class="price"><small>${esc(value(page.facts[1].label,lang))}</small><strong>${copy.price}</strong><span>${copy.per}</span></div></div><div class="stops">${rowHtml}</div></section><section class="fd-card include"><span class="fd-eyebrow">★ ${copy.confirmed}</span><h2>${copy.components}</h2><p>${esc(value(page.market,lang))}</p><div class="inc-grid">${[T('Traslado desde tu alojamiento','Traslado da hospedagem','Transfer from your accommodation')[lang],copy.sea,copy.meal,copy.land].map((x,i)=>`<div class="inc"><span>${String(i+1).padStart(2,'0')} · ${esc(T('A CONFIRMAR','A CONFIRMAR','TO CONFIRM')[lang])}</span><b>${esc(x)}</b><p>${esc(T('Confirma operación, disponibilidad, coste e inclusión para tu fecha.','Confirme operação, disponibilidade, custo e inclusão para sua data.','Confirm operation, availability, cost and inclusion for your date.')[lang])}</p></div>`).join('')}</div></section><section class="fd-card"><span class="fd-eyebrow">02 · ${copy.ask}</span><h2>${copy.what}</h2><p>${esc(copy.askCopy)}</p><div class="fd-practical-grid">${questions.map(([q,a])=>`<article><h3>${esc(q)}</h3><p>${esc(a)}</p></article>`).join('')}</div></section><section class="fd-card final"><div><span class="fd-eyebrow">${esc(value(page.facts[0].label,lang))}</span><h2>${copy.final}</h2><p>${esc(copy.finalCopy)}</p><strong>${copy.price}</strong><p>${esc(copy.per)}</p></div><a class="reserve" href="${esc(whatsappHref)}" target="_blank" rel="noopener noreferrer">${copy.cta}</a></section><section class="fd-card fd-inline-booking"><span class="fd-eyebrow">${copy.bookingEyebrow}</span><h2>${copy.bookingTitle}</h2><p>${esc(copy.bookingIntro)}</p><form class="form" data-bz-full-day-form><label>${esc(T('Nombre y apellido','Nome e sobrenome','Full name')[lang])}<input name="nombre" autocomplete="name" required></label><label>${esc(T('Fecha del viaje','Data da viagem','Travel date')[lang])}<input type="date" name="fecha" required></label><label>${esc(T('Cantidad de viajeros','Quantidade de viajantes','Number of travellers')[lang])}<input type="number" name="pasajeros" min="1" step="1" inputmode="numeric" required></label><label>${esc(T('Edades de menores','Idades das crianças','Children’s ages')[lang])}<input name="edades" inputmode="text"></label><label class="wide">${esc(T('Hotel o dirección de recogida','Hotel ou endereço para embarque','Hotel or pick-up address')[lang])}<input name="hotel" autocomplete="street-address" required></label><label>${esc(T('WhatsApp de contacto','WhatsApp para contato','Contact WhatsApp')[lang])}<input name="telefono" type="tel" autocomplete="tel" required></label><label class="wide">${esc(T('Consulta especial','Observação','Special request')[lang])}<textarea name="mensaje"></textarea></label><button class="send" type="submit">${copy.send}</button></form><p class="fd-booking-footnote">${esc(copy.footnote)}</p></section></div></section>`;
}

function bzContextPhoto(it,lang){const p=it&&it.photo;return p&&typeof p==='object'&&p.src&&/GUIA%20BUZIOS/i.test(p.src)?photoFigure(p,lang,false):'';}


const bzFirstQuarterGuides=[[{"ES":"Enero es uno de los meses más movidos: vacaciones, verano, restaurantes concurridos y playas con mucha demanda. Recomiendo llegar temprano, dejar el atardecer para Orla Bardot y reservar mesa y alojamiento con anticipación.","PT":"Janeiro é um dos meses mais movimentados: férias, verão, restaurantes cheios e muita procura por praias. Recomendo sair cedo, reservar o pôr do sol para a Orla Bardot e planejar mesa e hospedagem com antecedência.","EN":"January is a particularly busy month, with school holidays, summer crowds and strong demand for beaches and restaurants. Start early, enjoy Orla Bardot at sunset and book dining and accommodation ahead."},{"ES":"El calor y la humedad suelen acompañar jornadas soleadas, pero también puede llover fuerte por la tarde. Geribá es más expuesta al oleaje; Ferradura puede estar más protegida según el viento. Consulta el estado del mar antes de nadar y lleva agua y protección solar.","PT":"O calor e a umidade alternam sol com possíveis pancadas fortes de chuva. Geribá é mais exposta às ondas; Ferradura pode ser mais abrigada conforme o vento. Confira as condições do mar e leve água e proteção solar.","EN":"Heat and humidity may alternate with heavy afternoon showers. Geribá tends to be more exposed to surf; Ferradura can be sheltered depending on the wind. Check sea conditions and carry water and sun protection."},{"ES":"Antes de pagar alojamiento, calcula el costo total, cancelación y distancia real a playas y Centro. En vacaciones el traslado de regreso también merece una reserva anticipada. Mi consejo: una playa por la mañana, almuerzo tranquilo y paseo sin prisa por la tarde.","PT":"Antes de pagar hospedagem, confira valor total, cancelamento e distância real das praias e do Centro. Nas férias, planeje também o transporte de volta. Minha dica: praia cedo, almoço tranquilo e passeio no fim da tarde.","EN":"Before booking, compare total price, cancellation and real distances to beaches and town. Holiday return journeys also need planning. My tip: one beach in the morning, a relaxed lunch and an easy afternoon walk."}],[{"ES":"Febrero sigue siendo verano, pero el movimiento depende mucho de las fechas. Si Carnaval cae durante tu viaje, los feriados pueden aumentar la ocupación, la circulación y los precios. Comprueba la agenda municipal: nunca supongas que un bloco se repite igual todos los años.","PT":"Fevereiro continua sendo verão, mas o movimento muda muito conforme as datas. Quando o Carnaval coincide com a viagem, feriados podem elevar a ocupação e os preços. Confira a programação municipal, pois blocos e horários mudam.","EN":"February remains summery, but crowds vary greatly by date. When Carnival falls during your trip, holidays can increase demand and prices. Check the municipal calendar rather than assuming events recur unchanged."},{"ES":"Disfruta Geribá o Ferradura temprano; en Azeda y Azedinha el espacio es reducido y el acceso puede estar lleno. Después de lluvias intensas revisa la calidad del agua y evita confiar únicamente en fotos bonitas para elegir dónde bañarte.","PT":"Aproveite Geribá ou Ferradura cedo; Azeda e Azedinha têm pouco espaço e os acessos podem lotar. Após chuvas fortes, confira a qualidade da água e não escolha onde nadar apenas pelas fotos.","EN":"Go early to Geribá or Ferradura; Azeda and Azedinha have limited space and busy access routes. After heavy rain, check water quality and do not choose a swimming spot solely by its photographs."},{"ES":"Alterna playas con Rua das Pedras, Orla Bardot y buenas comidas. En paseos náuticos, pregunta por embarque, horarios, qué incluye el precio y las reglas por mal tiempo. Si viajas con menores, revisa pendientes, escaleras y el regreso al alojamiento.","PT":"Alterne praias com Rua das Pedras, Orla Bardot e boas refeições. Em passeios de barco, confirme embarque, horários, inclusões e regras de mau tempo. Com crianças, considere ladeiras, escadas e o trajeto de volta.","EN":"Balance beach time with Rua das Pedras, Orla Bardot and good food. For boat outings confirm boarding, schedules, inclusions and bad-weather rules. With children, consider hills, steps and the return journey."}],[{"ES":"Marzo puede ofrecer un ritmo más tranquilo después del pico del verano, aunque Carnaval, fines de semana y eventos cambian cada año. Es un buen momento para detenerse en cafés, gastronomía y caminatas, además de disfrutar el mar.","PT":"Março pode ter ritmo mais tranquilo após o auge do verão, embora Carnaval, fins de semana e eventos mudem a cada ano. É um ótimo momento para curtir cafés, gastronomia, caminhadas e praias.","EN":"March can bring a calmer pace after peak summer, although Carnival, weekends and events change the picture. It is a good time for cafés, dining and walks as well as beaches."},{"ES":"El calor puede continuar y los chaparrones siguen siendo posibles. Mira el viento antes de elegir playa: Geribá, Ferradura y João Fernandes ofrecen ambientes diferentes. Si llueve, reorganiza el día con paseos urbanos, compras y una comida tranquila.","PT":"O calor pode continuar e ainda há pancadas de chuva. Observe o vento antes de escolher entre Geribá, Ferradura e João Fernandes. Se chover, mude a programação para passeios urbanos, compras e uma refeição tranquila.","EN":"Warm weather and showers can continue. Check wind conditions before choosing between Geribá, Ferradura and João Fernandes. In rain, switch to town walks, shopping and a relaxed meal."},{"ES":"Para una primera estadía, alojarse cerca del Centro facilita volver caminando después de cenar; si tu prioridad es despertar junto al mar, compara distancias y pendientes. Menos visitantes no garantizan precios bajos: confirma todas las tasas, cancelación y traslados.","PT":"Na primeira viagem, ficar perto do Centro facilita voltar a pé após jantar; para acordar perto do mar, compare distância e ladeiras. Menos visitantes não garantem preços menores: confira taxas, cancelamento e traslados.","EN":"Staying near the centre makes walking back after dinner easier on a first visit; a beach-focused stay requires comparing distances and slopes. Fewer visitors do not guarantee low rates: verify all fees, cancellation and transfers."}]];
const bzMmFacts={"climate":[[24,27,130],[24,28,82],[24,27,127],[23,26,71],[21,24,62],[20,24,37],[19,23,38],[19,24,35],[20,24,59],[21,25,81],[22,25,142],[23,27,147]],"crowd":[["Muy concurrido: vacaciones y fines de semana de temporada alta.","Muito movimentado: férias e fins de semana de alta temporada.","Very busy: school holidays and peak-season weekends."],["Alto en fines de semana y Carnaval cuando coincide con febrero.","Alto nos fins de semana e no Carnaval quando ocorre em fevereiro.","Busy on weekends and when Carnival falls in February."],["Más tranquilo entre semana, salvo Carnaval o feriados.","Mais tranquilo nos dias úteis, salvo Carnaval ou feriados.","Quieter on weekdays, except Carnival or holidays."],["Movimiento moderado; Semana Santa puede llenar la ciudad.","Movimento moderado; a Semana Santa pode lotar a cidade.","Moderate crowds; Easter can bring a surge."],["Generalmente más tranquilo, salvo feriados y fines de semana.","Em geral mais tranquilo, exceto feriados e fins de semana.","Generally quieter, except holidays and weekends."],["Temporada más calmada, con picos en feriados.","Época mais calma, com picos em feriados.","Typically calmer, with occasional holiday peaks."],["Vacaciones escolares elevan el movimiento, sobre todo fines de semana.","Férias escolares aumentam o movimento, sobretudo nos fins de semana.","School holidays can increase crowds, especially weekends."],["Habitualmente tranquilo, pero puede haber días ventosos.","Geralmente tranquilo, mas alguns dias podem ser ventosos.","Often quiet, though some days can be windy."],["Mayor calma fuera de fines de semana y feriados.","Mais sossegado fora de fins de semana e feriados.","Usually quieter outside weekends and holidays."],["La demanda sube con feriados y fines de semana.","A procura cresce em feriados e fins de semana.","Holiday weekends can raise demand."],["Movimiento variable; los feriados pueden encarecer estadías.","Movimento variável; feriados podem elevar preços.","Variable crowds; holidays may push up rates."],["Aumenta mucho hacia Navidad y Año Nuevo: reserva temprano.","Movimento cresce muito perto do Natal e Réveillon: reserve cedo.","Crowds rise sharply around Christmas and New Year: book early."]],"tips":[["Sal temprano hacia la playa, reserva alojamiento y organiza el regreso.","Vá cedo à praia, reserve hospedagem e planeje a volta.","Go to beaches early, book your stay and plan your return."],["Revisa fechas de Carnaval, evita horas punta y reserva el traslado.","Confira as datas do Carnaval, evite horários de pico e reserve o traslado.","Check Carnival dates, avoid rush hours and arrange transfers."],["Aprovecha días de semana para playas populares y deja un plan para lluvia.","Aproveite os dias úteis nas praias populares e tenha um plano de chuva.","Use weekdays for popular beaches and have a rain plan."],["Si coincide Semana Santa, reserva antes; combina playas y paseos.","Se coincidir com a Semana Santa, reserve antes; combine praias e passeios.","Book ahead around Easter; mix beaches and walks."],["Ideal para caminar y cenar sin apuro; lleva algo para la noche.","Bom para caminhar e jantar sem pressa; leve um agasalho leve.","Enjoy relaxed walks and dinners; take a light layer."],["Busca días soleados para paseos náuticos y lleva abrigo liviano.","Escolha dias de sol para passeios de barco e leve agasalho leve.","Choose sunny days for boat trips and pack a light layer."],["Para bañarte, compara viento y oleaje; reserva en vacaciones escolares.","Para nadar, confira vento e ondas; reserve nas férias escolares.","Check wind and surf before swimming; book during school holidays."],["Confirma viento y salidas al mar; disfruta los miradores y atardeceres.","Confira vento e saídas de barco; aproveite mirantes e pôr do sol.","Check winds and boat outings; enjoy viewpoints and sunsets."],["Aprovecha las caminatas y lleva una capa ligera para la brisa.","Aproveite caminhadas e leve uma camada leve para a brisa.","Enjoy walks and pack a light layer for the breeze."],["Compara feriados antes de reservar y elige playas según el viento.","Compare feriados antes de reservar e escolha praias conforme o vento.","Check holiday dates before booking and choose beaches for the wind."],["Ten alternativas para lluvia y revisa cancelaciones de paseos.","Tenha opções para chuva e confira cancelamentos de passeios.","Have rainy-day alternatives and check tour cancellation terms."],["Reserva alojamiento y transportes con anticipación para fin de año.","Reserve hospedagem e transporte cedo para o fim de ano.","Book accommodation and transport early for year-end."]],"beach":[["Geribá para surf; Ferradura según viento; Azeda temprano.","Geribá para surfe; Ferradura conforme vento; Azeda cedo.","Geribá for surf; Ferradura depending on wind; Azeda early."],["Geribá, Ferradura y João Fernandes temprano para evitar multitudes.","Geribá, Ferradura e João Fernandes cedo para evitar lotação.","Visit Geribá, Ferradura and João Fernandes early to beat crowds."],["Ferradura o João Fernandes si el mar acompaña; Geribá para surf.","Ferradura ou João Fernandes se o mar permitir; Geribá para surfe.","Ferradura or João Fernandes when the sea allows; Geribá for surf."]]};
const bzSecondQuarterGuides=[[{"title":{"ES":"Abril: otoño y Semana Santa","PT":"Abril: outono e Semana Santa","EN":"April: autumn and Easter"},"body":{"ES":"En abril Búzios va dejando atrás la intensidad del verano y es posible encontrar calles y playas más tranquilas durante la semana. Pero Semana Santa, cuando cae en abril, puede devolver la ciudad a un ambiente de alta ocupación durante varios días. Recomiendo elegir alojamiento pensando en los desplazamientos reales: cerca del Centro para salir a cenar caminando o en zonas de playa si buscas mañanas junto al mar. Verifica las fechas de feriados antes de reservar.","PT":"Em abril, Búzios começa a deixar para trás a intensidade do verão, e os dias úteis podem ser mais tranquilos. Mas a Semana Santa, quando acontece em abril, pode elevar a lotação por vários dias. Escolha hospedagem considerando deslocamentos reais: perto do Centro para jantar a pé ou em regiões de praia para acordar junto ao mar. Confira os feriados antes de reservar.","EN":"In April, Búzios begins to ease out of its busiest summer rhythm; weekdays can be notably calmer. Easter, when it falls in April, can bring several very busy days. Choose accommodation based on real travel needs: near the centre for evening walks or closer to a beach for early mornings by the sea. Check holiday dates before booking."}},{"title":{"ES":"Tiempo, playa y alternativas","PT":"Tempo, praia e alternativas","EN":"Weather, beaches and alternatives"},"body":{"ES":"El calor suele ser menos intenso que en pleno verano, aunque sigue habiendo días agradables de playa y lluvias posibles. No elijas solo por el calendario: una mañana soleada puede servir para Ferradura o João Fernandes, mientras que Geribá exige más atención al oleaje. Lleva una prenda liviana para la noche y ten alternativas para lluvia: cafés, restaurantes, Rua das Pedras y paseos urbanos.","PT":"O calor costuma diminuir em relação ao auge do verão, mas ainda há dias agradáveis de praia e possibilidade de chuva. Não escolha apenas pelo calendário: uma manhã de sol pode combinar com Ferradura ou João Fernandes, enquanto Geribá exige atenção às ondas. Leve uma peça leve para a noite e tenha opções para chuva, como cafés, restaurantes e a Rua das Pedras.","EN":"Heat often eases compared with midsummer, but there are still pleasant beach days and occasional showers. Do not choose a beach by month alone: Ferradura or João Fernandes may work on a settled morning, while Geribá needs closer attention to surf. Pack a light evening layer and keep cafés, restaurants and town walks as rain alternatives."}},{"title":{"ES":"Cómo aprovechar abril","PT":"Como aproveitar abril","EN":"Making the most of April"},"body":{"ES":"Mi consejo es no sobrecargar el itinerario: una playa por la mañana, almuerzo largo y una caminata por Orla Bardot al atardecer. Si viajas durante feriados, reserva alojamiento y traslados con tiempo y confirma las reglas de cancelación. Fuera de esos picos, puedes comparar hospedajes y actividades con más flexibilidad, pero nunca des por hecho que los valores serán bajos.","PT":"Minha dica é não lotar o roteiro: praia pela manhã, almoço sem pressa e caminhada na Orla Bardot ao entardecer. Nos feriados, reserve hospedagem e traslado com antecedência e confira cancelamento. Fora desses picos, há mais flexibilidade para comparar opções, mas preços baixos não são garantidos.","EN":"My advice: do not overpack the day. Try a morning beach, a lingering lunch and an Orla Bardot walk at sunset. Around holidays, reserve accommodation and transfers early and check cancellation terms. Outside those peaks, comparison shopping may be easier, but low prices are not guaranteed."}}],[{"title":{"ES":"Mayo: Búzios sin tanta prisa","PT":"Maio: Búzios sem tanta pressa","EN":"May: a slower Búzios"},"body":{"ES":"Mayo suele ser un mes agradable para quienes priorizan caminar, conocer barrios, comer bien y disfrutar playas sin el movimiento máximo del verano. Entre semana el ambiente puede ser más tranquilo, aunque el clima, los feriados y los eventos hacen variar la ocupación. Es una buena oportunidad para explorar Manguinhos, la Orla Bardot y la zona de Rua das Pedras con tiempo para entrar a cafés y restaurantes.","PT":"Maio costuma ser agradável para quem prefere caminhar, conhecer bairros, comer bem e aproveitar praias sem o pico de movimento do verão. Durante a semana pode ser mais sossegado, mas clima, feriados e eventos mudam a ocupação. Aproveite para conhecer Manguinhos, a Orla Bardot e a Rua das Pedras com tempo para cafés e restaurantes.","EN":"May often suits travellers who prefer walking, exploring neighbourhoods and good food without peak-summer bustle. Weekdays may be quieter, although weather, holidays and events still shape demand. Explore Manguinhos, Orla Bardot and Rua das Pedras at an unhurried pace, with time for cafés and restaurants."}},{"title":{"ES":"Temperaturas y mar","PT":"Temperaturas e mar","EN":"Temperatures and sea"},"body":{"ES":"Las temperaturas acostumbran a ser más suaves: las mañanas pueden invitar a la playa, mientras la brisa de tarde y la noche piden una capa liviana. El mar no siempre está igual de tranquilo: Ferradura es una alternativa para evaluar según viento, Geribá es más expuesta y João Fernandes combina paisaje con servicios según temporada. Comprueba condiciones antes de nadar y no prometas un día de barco sin verificar el tiempo.","PT":"As temperaturas ficam mais amenas: a manhã pode ser boa para praia, enquanto a brisa da tarde e a noite pedem um agasalho leve. O mar varia: Ferradura pode ser alternativa conforme o vento, Geribá é mais exposta e João Fernandes oferece paisagem e estrutura que depende da época. Confira as condições antes de nadar ou embarcar.","EN":"Temperatures are typically milder: mornings may be beach-friendly while afternoon breezes and evenings call for a light layer. Sea conditions still vary: assess Ferradura according to wind, remember Geribá is more exposed, and check services at João Fernandes. Confirm conditions before swimming or booking a boat day."}},{"title":{"ES":"Gastronomía, alojamiento y presupuesto","PT":"Gastronomia, hospedagem e orçamento","EN":"Food, accommodation and budgets"},"body":{"ES":"Si el plan es romántico o tranquilo, combina una mañana en la costa con un almuerzo en Porto da Barra o una cena en el Centro. Antes de elegir hotel, revisa pendientes, distancia a las paradas y cómo volverás después de cenar. Compara precio total, tasas y cancelación: menor ocupación no garantiza descuentos. Lleva protección solar incluso en días frescos y una opción de abrigo para paseos nocturnos.","PT":"Para uma viagem romântica ou tranquila, combine manhã no litoral com almoço no Porto da Barra ou jantar no Centro. Antes de escolher hotel, veja ladeiras, distância do transporte e como voltar depois de jantar. Compare preço total, taxas e cancelamento: movimento menor não garante desconto. Leve protetor solar e agasalho leve à noite.","EN":"For a romantic or low-key trip, pair a coastal morning with lunch around Porto da Barra or dinner in the centre. Before picking a hotel, check slopes, public transport and how to return after dinner. Compare total rates, fees and cancellation: fewer guests do not ensure discounts. Bring sun protection and a light evening layer."}}],[{"title":{"ES":"Junio: invierno suave junto al mar","PT":"Junho: inverno ameno à beira-mar","EN":"June: a mild coastal winter"},"body":{"ES":"Junio trae días generalmente más frescos que en verano y puede ser un período atractivo para pasear, comer con calma y conocer el Centro sin el mismo nivel de calor. En vacaciones y feriados puntuales puede haber más visitantes, por lo que el movimiento no será igual todos los días. El invierno de Búzios no significa frío extremo, pero la sensación térmica cambia con el viento, especialmente cerca del agua.","PT":"Junho traz dias mais frescos que no verão e pode ser ótimo para caminhar, comer com calma e conhecer o Centro sem tanto calor. Feriados e datas especiais ainda atraem visitantes, por isso o movimento muda. O inverno de Búzios não costuma ser rigoroso, mas o vento altera bastante a sensação térmica perto do mar.","EN":"June brings cooler days than summer and can be ideal for walking, enjoying meals and exploring town without intense heat. Holidays and special weekends can still bring crowds. Búzios winter is generally mild rather than bitterly cold, but the wind can make waterfront areas feel cooler."}},{"title":{"ES":"Playas, viento y planes de mar","PT":"Praias, vento e passeios no mar","EN":"Beaches, wind and sea outings"},"body":{"ES":"Puede haber mañanas soleadas que invitan a sentarse en la arena o incluso bañarse, pero no conviene asegurar agua tibia ni mar calmo. Comprueba viento, oleaje y condiciones de baño antes de elegir entre Geribá, Ferradura y João Fernandes. Para paseos de barco, pregunta por horario, embarque y condiciones de cancelación por mal tiempo. Siempre vale la pena llevar algo para cubrirse después del atardecer.","PT":"Pode haver manhãs ensolaradas boas para ficar na areia ou até entrar na água, mas não conte sempre com mar quente e calmo. Confira vento, ondas e banho antes de escolher Geribá, Ferradura ou João Fernandes. Para barco, confirme horários, embarque e cancelamento por mau tempo. Leve algo para se cobrir depois do pôr do sol.","EN":"Sunny mornings may still be good for relaxing on the sand or even swimming, but warm water and calm seas are never guaranteed. Check wind and surf before choosing among Geribá, Ferradura and João Fernandes. Ask boat operators about boarding times and bad-weather cancellation. Pack an extra layer for after sunset."}},{"title":{"ES":"Qué hacer en junio","PT":"O que fazer em junho","EN":"What to do in June"},"body":{"ES":"Mi plan favorito sería empezar con un café sin apuro, recorrer la Orla Bardot, visitar miradores cuando el día esté despejado y terminar con una buena cena. Junio funciona muy bien para quienes valoran gastronomía y caminatas tanto como playas. Si tu viaje coincide con un feriado, reserva traslados y hospedaje con antelación; si viajas entre semana, aprovecha para comparar zonas y ritmos sin la presión del verano.","PT":"Meu plano favorito: café da manhã tranquilo, caminhada pela Orla Bardot, mirantes em dia aberto e um bom jantar. Junho combina com quem gosta tanto de gastronomia e caminhadas quanto de praia. Em feriados, reserve traslado e hospedagem; durante a semana, aproveite para comparar regiões com calma.","EN":"My favourite plan is a slow breakfast, an Orla Bardot walk, viewpoints on a clear day and a good dinner. June is especially rewarding if food and walking matter as much as the beach. Around holidays, reserve transport and accommodation; on weekdays, take advantage of the more relaxed pace."}}]];
const bzThirdQuarterGuides=[[{"ES":"Julio coincide con vacaciones escolares brasileñas y los fines de semana pueden ser concurridos. Fuera de esos picos, los paseos por Orla Bardot, las cafeterías y la gastronomía permiten disfrutar de Búzios con otro ritmo. Conviene reservar alojamiento y transporte cuando coincidan vacaciones.","PT":"Julho coincide com férias escolares brasileiras e os fins de semana podem ficar movimentados. Fora desses picos, a Orla Bardot, os cafés e a gastronomia permitem curtir Búzios com outro ritmo. Reserve hospedagem e transporte nas férias.","EN":"July coincides with Brazilian school holidays, so weekends can be busy. Outside these peaks, Orla Bardot, cafés and local dining offer a more relaxed Búzios experience. Book accommodation and transport for holiday dates."},{"ES":"El invierno suele ser suave, pero la brisa nocturna puede sentirse fresca. Un día soleado no garantiza mar cálido: comprueba oleaje, viento y señalización. Geribá es más expuesta y Ferradura puede estar más resguardada, según las condiciones de cada jornada.","PT":"O inverno costuma ser ameno, mas a brisa da noite pode esfriar. Sol não garante mar quente: confira ondas, vento e sinalização. Geribá é mais exposta e Ferradura pode ser mais abrigada conforme as condições.","EN":"Winter is often mild, but evening breezes can feel cool. Sunshine does not guarantee warm water: check surf, wind and beach warnings. Geribá is more exposed; Ferradura may be sheltered depending on conditions."},{"ES":"Yo combinaría una playa o un mirador por la mañana con un paseo por Rua das Pedras y una cena tranquila. Para salidas de barco, confirma embarque, viento previsto y cancelación. Viajar con niños requiere revisar pendientes y accesos, no solo las fotografías.","PT":"Eu combinaria praia ou mirante pela manhã com Rua das Pedras e jantar tranquilo. Para passeios de barco, confirme embarque, vento e cancelamento. Com crianças, confira ladeiras e acessos, não só fotos.","EN":"I would pair a morning beach or viewpoint with Rua das Pedras and a relaxed dinner. For boat outings confirm boarding, wind and cancellation policies. With children, check slopes and access rather than relying on photos."}],[{"ES":"Agosto suele ser más tranquilo fuera de feriados y eventos, ideal para caminatas, miradores y gastronomía sin las aglomeraciones del verano. Algunos operadores pueden trabajar con horarios reducidos: confirma antes de planificar un itinerario largo.","PT":"Agosto costuma ser mais tranquilo fora de feriados e eventos, ótimo para caminhadas, mirantes e gastronomia sem a lotação do verão. Alguns serviços podem ter horários reduzidos; confirme antes de planejar.","EN":"August is often quieter outside holidays and events, good for walks, viewpoints and dining without summer crowds. Some operators may have reduced hours; check before planning a long itinerary."},{"ES":"El viento puede cambiar mucho la experiencia de playa. Geribá recibe más oleaje; Ferradura y João Fernandes merecen evaluarse según dirección del viento y condiciones del mar. Si el tiempo no acompaña, sustituye la salida náutica por un recorrido urbano.","PT":"O vento pode mudar bastante a experiência. Geribá é mais exposta às ondas; avalie Ferradura e João Fernandes conforme o vento e o mar. Se o tempo não ajudar, troque o passeio de barco por um passeio urbano.","EN":"Wind can dramatically change the beach experience. Geribá is more exposed to surf; assess Ferradura and João Fernandes based on wind direction and sea conditions. Choose town activities over boat trips if conditions are poor."},{"ES":"Si piensas salir a cenar, busca alojamiento bien conectado con el Centro para evitar traslados innecesarios. Lleva protector solar para las horas despejadas y una chaqueta liviana para la tarde. Compara precios finales: menos visitantes no garantiza descuentos.","PT":"Para jantar fora, escolha hospedagem bem conectada ao Centro. Leve protetor solar para o dia e agasalho leve para a tarde. Compare valores finais: menos visitantes não garante descontos.","EN":"If you plan evenings out, stay within easy reach of downtown. Bring sunscreen for sunny hours and a light layer for later. Compare total rates: fewer visitors do not guarantee discounts."}],[{"ES":"Septiembre anuncia la primavera y, fuera de feriados, puede ofrecer una ciudad más serena que en pleno verano. El movimiento crece los fines de semana; revisa el calendario brasileño y reserva las fechas especiales con tiempo.","PT":"Setembro anuncia a primavera e pode trazer dias mais sossegados que o verão fora dos feriados. O movimento aumenta nos fins de semana; confira o calendário brasileiro e reserve datas especiais.","EN":"September marks spring and can be quieter than peak summer outside holidays. Weekends attract visitors, so check Brazil's holiday calendar and book special dates early."},{"ES":"Los días pueden sentirse más cálidos, pero la primavera no asegura mar calmo. Decide entre Geribá, Ferradura y João Fernandes según viento y oleaje; verifica señalización local antes de nadar. Empaca ropa ligera y una capa adicional para la brisa.","PT":"Os dias podem esquentar, mas primavera não garante mar calmo. Escolha entre Geribá, Ferradura e João Fernandes conforme vento e ondas; confira a sinalização. Leve roupas leves e uma camada extra.","EN":"Days may be warmer, but spring does not guarantee calm seas. Choose between Geribá, Ferradura and João Fernandes by wind and surf; heed local warnings. Pack light clothing and an extra layer."},{"ES":"Aprovecharía la mañana junto al mar, almorzaría sin apuro y reservaría el atardecer para Orla Bardot. También exploraría cafés y restaurantes con calma, revisando los horarios de funcionamiento y el regreso al alojamiento.","PT":"Eu aproveitaria a manhã à beira-mar, almoçaria sem pressa e deixaria o pôr do sol para a Orla Bardot. Também exploraria cafés e restaurantes com calma, conferindo horários e como voltar à hospedagem.","EN":"I would enjoy a coastal morning, an unhurried lunch and sunset at Orla Bardot. Explore cafés and restaurants at a slower pace, checking hours and how to return to your accommodation."}]];
const bzFourthQuarterGuides=[[{"ES":"Octubre abre la etapa de primavera más cálida, con días agradables para combinar playas y paseos. No es todavía el movimiento continuo de enero, pero los fines de semana y feriados —incluido el de octubre en Brasil— pueden llenar alojamientos y accesos. Si quieres descansar, compara fechas laborales y reserva con anticipación para fines de semana largos.","PT":"Outubro traz uma primavera mais quente, com dias agradáveis para praias e passeios. Ainda não é o movimento contínuo de janeiro, mas fins de semana e feriados — inclusive os de outubro no Brasil — podem lotar hospedagens e acessos. Para descansar, compare dias úteis e reserve cedo nos feriadões.","EN":"October brings warmer spring weather, good for mixing beach days and exploring. It is not yet as continuously busy as January, but weekends and Brazilian holidays in October can crowd accommodation and access roads. For a calmer visit, choose weekdays and book holiday weekends early."},{"ES":"Las temperaturas suelen subir gradualmente y pueden alternarse sol, brisa y lluvia. Geribá es atractiva para quienes buscan olas, mientras Ferradura o João Fernandes pueden funcionar mejor dependiendo del viento. Antes de salir, mira la previsión del día y el estado del mar: ni el calor garantiza aguas tranquilas ni la primavera elimina los chaparrones.","PT":"As temperaturas sobem aos poucos e podem alternar sol, brisa e chuva. Geribá atrai quem busca ondas, enquanto Ferradura ou João Fernandes podem funcionar melhor conforme o vento. Antes de sair, confira a previsão e o mar: calor não garante águas calmas e primavera não elimina pancadas de chuva.","EN":"Temperatures generally rise, with sunshine, breezes and showers all possible. Geribá attracts surfers, while Ferradura or João Fernandes may suit calmer-water plans depending on wind. Check the day's forecast and sea conditions: warm air does not guarantee safe, calm water."},{"ES":"Mi itinerario para octubre: desayunar temprano, conocer una playa según las condiciones, almorzar con calma y dejar Orla Bardot para la luz del atardecer. Si llegas desde Río, ten en cuenta el tránsito en feriados y calcula el traslado hasta la puerta del alojamiento. Compara la tarifa total, tasas y cancelaciones antes de pagar.","PT":"Meu roteiro para outubro: café da manhã cedo, praia conforme as condições, almoço tranquilo e Orla Bardot na luz do fim da tarde. Vindo do Rio, considere o trânsito nos feriados e planeje o trajeto até a hospedagem. Compare o valor total, taxas e cancelamento antes de pagar.","EN":"My October plan: an early breakfast, a beach chosen for the conditions, a relaxed lunch and Orla Bardot in the late-afternoon light. Travelling from Rio? Allow for holiday traffic and plan the last leg to your accommodation. Compare full prices, fees and cancellation terms."}],[{"ES":"Noviembre anuncia el verano cercano y un ambiente que empieza a ganar energía. Puede seguir siendo más tranquilo que diciembre o enero en días laborales, pero feriados nacionales y eventos locales cambian rápidamente la ocupación. Es un buen momento para viajar si te gusta combinar playas con gastronomía y noches en el Centro, sin depender de un calendario fijo de eventos.","PT":"Novembro anuncia a chegada do verão e um clima de mais movimento. Dias úteis podem ser mais tranquilos que dezembro ou janeiro, mas feriados nacionais e eventos locais alteram a ocupação. É uma boa época para combinar praias, gastronomia e noites no Centro sem depender de agenda fixa.","EN":"November approaches summer and the town begins to feel livelier. Weekdays may be calmer than December or January, but national holidays and local events can change demand quickly. It suits travellers who want beaches, food and evenings downtown without relying on any fixed event calendar."},{"ES":"El tiempo se vuelve más cálido y húmedo, con posibilidad de lluvias de primavera. Alterna playas según la dirección del viento y el oleaje: Geribá suele ser más abierta; Ferradura ofrece una bahía y João Fernandes una cala concurrida según el día. Después de lluvias fuertes, consulta la condición del agua antes de bañarte y lleva siempre protección solar.","PT":"O tempo fica mais quente e úmido, com possibilidade de chuvas de primavera. Escolha praias conforme vento e ondas: Geribá é mais aberta; Ferradura fica em uma enseada e João Fernandes pode estar movimentada. Após chuva forte, confira a qualidade da água antes do banho e use proteção solar.","EN":"Weather gets warmer and more humid, with spring showers possible. Choose beaches by wind and swell: Geribá is more exposed, Ferradura sits in a bay and João Fernandes can become busy. After heavy rain check water conditions before swimming, and carry sun protection."},{"ES":"Yo reservaría una mañana para Geribá o Ferradura, una tarde para cafés y tiendas de Rua das Pedras y una cena frente al mar si encuentro disponibilidad. Organiza el regreso antes de salir por la noche y pregunta por las condiciones de cancelación en paseos náuticos. No confundas menor ocupación entre semana con garantía de precios bajos.","PT":"Eu reservaria uma manhã para Geribá ou Ferradura, tarde para cafés e lojas da Rua das Pedras e jantar à beira-mar, conforme disponibilidade. Planeje a volta antes de sair à noite e confira cancelamento em passeios náuticos. Menor ocupação nos dias úteis não garante preços baixos.","EN":"I would save a morning for Geribá or Ferradura, an afternoon for Rua das Pedras cafés and shops, and dinner overlooking the sea if available. Arrange your return before going out and check boat-tour cancellation terms. Quieter weekdays do not automatically mean lower prices."}],[{"ES":"Diciembre cambia de ritmo a medida que avanzan las semanas. Al comienzo todavía puede haber jornadas relativamente tranquilas, pero Navidad y Año Nuevo elevan mucho la demanda de alojamiento, restaurantes y transporte. Si planeas pasar las fiestas en Búzios, reserva con mucha anticipación y confirma la programación oficial: no todos los eventos, escenarios o fuegos artificiales se repiten año tras año.","PT":"Dezembro muda de ritmo ao longo das semanas. No início ainda pode haver dias tranquilos, mas Natal e Réveillon aumentam muito a procura por hospedagem, restaurantes e transporte. Se passar as festas em Búzios, reserve com antecedência e confira a programação oficial: eventos, palcos e fogos não se repetem obrigatoriamente todos os anos.","EN":"December changes pace as the month progresses. Early weeks may still feel relatively quiet, while Christmas and New Year bring high demand for accommodation, dining and transport. Book festivities well ahead and verify official programmes: event locations, stages and fireworks do not necessarily recur each year."},{"ES":"El verano trae calor, humedad y posibilidad de lluvias fuertes, a menudo breves pero intensas. Los días soleados invitan a la playa, aunque la seguridad depende del oleaje y la calidad del agua, no del mes. En Azeda y Azedinha el espacio puede agotarse temprano; en Geribá las olas pueden ser exigentes. Planea alternativas bajo techo si llega una tormenta.","PT":"O verão traz calor, umidade e possibilidade de pancadas fortes de chuva. Dias de sol convidam à praia, mas a segurança depende de ondas e qualidade da água, não do mês. Azeda e Azedinha podem lotar cedo; em Geribá as ondas podem ser fortes. Tenha alternativas em locais cobertos para tempestades.","EN":"Summer brings heat, humidity and possible heavy downpours, sometimes short but intense. Sunny days invite beach trips, but safety depends on surf and water quality, not the month. Azeda and Azedinha can fill early, while Geribá may have powerful waves. Keep indoor alternatives for thunderstorms."},{"ES":"Mi recomendación para diciembre es sencilla: no intentes hacer todo durante las horas de mayor movimiento. Sale temprano hacia la playa, reserva mesa si cenarás en fechas festivas y coordina tu transporte de regreso antes de salir. Comprueba la ubicación exacta del alojamiento y las reglas de cancelación, especialmente si viajas en familia o con mucho equipaje.","PT":"Minha dica para dezembro é simples: não tente fazer tudo nos horários mais movimentados. Vá cedo à praia, reserve mesa para as festas e organize a volta antes de sair. Confira a localização exata da hospedagem e as regras de cancelamento, especialmente com família ou muita bagagem.","EN":"My December advice is simple: avoid packing everything into the busiest hours. Go to the beach early, reserve restaurants for festive dates and arrange your journey back before heading out. Verify accommodation location and cancellation policies, especially with family or lots of luggage."}]];
function renderBuziosMonthEditorial(page,lang,sections){
 const tr=(es,pt,en)=>({ES:es,PT:pt,EN:en})[lang];
 const months=(sections[0]?.items||[]).slice(0,12);
 const abbreviations={ES:['ENE','FEB','MAR','ABR','MAY','JUN','JUL','AGO','SEP','OCT','NOV','DIC'],PT:['JAN','FEV','MAR','ABR','MAI','JUN','JUL','AGO','SET','OUT','NOV','DEZ'],EN:['JAN','FEB','MAR','APR','MAY','JUN','JUL','AUG','SEP','OCT','NOV','DEC']}[lang];
 const descriptions=[
 tr('Verano','Verão','Summer'),tr('Playas','Praias','Beaches'),tr('Calma','Calma','Calm'),tr('Escapadas','Escapadas','Getaways'),tr('Tranquilidad','Tranquilidade','Quiet'),tr('Naturaleza','Natureza','Nature'),tr('Invierno suave','Inverno ameno','Mild winter'),tr('Paseos','Passeios','Exploring'),tr('Primavera','Primavera','Spring'),tr('Buen clima','Clima agradável','Pleasant weather'),tr('Menos gente','Menos movimento','Quieter'),tr('Verano llega','Verão chegando','Summer arrives')];
 const photos=[
 'minitatura%20para%20playas%20buzios.jpg',
 'miniatura%20buzios%20segun%20tu%20forma%20de%20viajar.jpg',
 'miniatura%20una%20zona%20para%20cada%20ritmo.jpg',
 'minitatura%20para%20experiencias%20buzios.jpg',
 'miniatura%20buzios%20mes%20a%20mes.jpeg',
 'miniatura%20cruceros%20en%20buzios%20MSC-Armonia-Buzios.jpg',
 'minitatura%20para%20playas%20buzios.jpg',
 'miniatura%20buzios%20mes%20a%20mes.jpeg',
 'miniatura%20una%20zona%20para%20cada%20ritmo.jpg',
 'minitatura%20para%20experiencias%20buzios.jpg',
 'minitatura%20para%20playas%20buzios.jpg',
 'miniatura%20buzios%20mes%20a%20mes.jpeg'];
 const base='https://mediumturquoise-stinkbug-270478.hostingersite.com/FOTOS/HOME/BUZIOS/';
 const photo=(i)=>base+photos[i%photos.length];
 const card=(it,i)=>'<button class="bz-mm-month" type="button" data-mm-select="'+i+'" aria-pressed="'+(i===0?'true':'false')+'"><img alt="" loading="lazy" src="'+photo(i)+'"><strong>'+abbreviations[i]+'</strong><small>'+descriptions[i]+'</small></button>';
 const mmFact=(kind,i)=>bzMmFacts[kind][i]?.[lang==='ES'?0:lang==='PT'?1:2]||'';
 const mmClimate=(i)=>{const [low,high,rain]=bzMmFacts.climate[i];return tr('Habitualmente '+low+'–'+high+' °C; lluvia media '+rain+' mm/mes.','Em média '+low+'–'+high+' °C; chuva média '+rain+' mm/mês.','Typical '+low+'–'+high+' °C; average rainfall '+rain+' mm/month.');};
 const mmBeaches=(i)=>bzMmFacts.beach[i]?.[lang==='ES'?0:lang==='PT'?1:2]||tr('Elige según viento, oleaje y acceso del día.','Escolha conforme vento, ondas e acesso do dia.','Choose by wind, surf and access on the day.');
 const details=months.map((it,i)=>'<article class="bz-mm-detail" data-mm-panel="'+i+'"'+(i?' hidden':'')+'><div class="bz-mm-feature-photo"><img src="'+photo(i)+'" alt="" loading="lazy"><div><small>'+esc(tr('MES DESTACADO','MÊS EM DESTAQUE','FEATURED MONTH'))+'</small><h2>'+esc(value(it.title,lang))+'</h2><p>'+esc(value(it.text,lang))+'</p></div></div><div class="bz-mm-feature-info"><div class="bz-mm-facts"><section><span>☀</span><b>'+esc(tr('CLIMA','CLIMA','WEATHER'))+'</b><p>'+esc(mmClimate(i))+'</p></section><section><span>☂</span><b>'+esc(tr('PLAYAS IDEALES','PRAIAS IDEAIS','IDEAL BEACHES'))+'</b><p>'+esc(mmBeaches(i))+'</p></section><section><span>♧</span><b>'+esc(tr('AMBIENTE TURÍSTICO','MOVIMENTO TURÍSTICO','VISITOR ATMOSPHERE'))+'</b><p>'+esc(mmFact('crowd',i))+'</p></section><section><span>♡</span><b>'+esc(tr('NUESTROS CONSEJOS','NOSSAS DICAS','OUR TIPS'))+'</b><p>'+esc(mmFact('tips',i))+'</p></section></div><aside class="bz-mm-tip"><span>✺</span><div><h3>'+esc(tr('Dato de Ernestinho','Dica do Ernestinho','Ernestinho’s tip'))+'</h3><p>'+esc(tr('Deja espacio para un paseo espontáneo, una playa y una comida tranquila.','Deixe tempo para um passeio espontâneo, praia e uma refeição tranquila.','Leave time for a spontaneous walk, beach visit and a leisurely meal.'))+'</p></div></aside></div>'+(i<12?'<div class="bz-mm-deep"><h3>'+esc(value(it.title,lang))+' · '+esc(tr('guía completa','guia completa','complete guide'))+'</h3>'+(i<3?bzFirstQuarterGuides[i]:i<6?bzSecondQuarterGuides[i-3].map(b=>b.body):i<9?bzThirdQuarterGuides[i-6]:bzFourthQuarterGuides[i-9]).map((para,j)=>'<p><strong>'+esc([tr('Ambiente y temporada','Ambiente e temporada','Season and atmosphere'),tr('Clima y playas','Clima e praias','Weather and beaches'),tr('Consejos prácticos','Dicas práticas','Practical advice')][j])+'</strong> '+esc(para[lang])+'</p>').join('')+'</div>':'')+'</article>').join('');
 const lifestyles=[
 [tr('Viaje en familia','Viagem em família','Family trip'),tr('Playas, paseos y días sin apuro.','Praias, passeios e dias sem pressa.','Beaches and easy-going days.'),'minitatura%20para%20playas%20buzios.jpg'],
 [tr('Más tranquilidad','Mais tranquilidade','More peaceful days'),tr('Busca días laborables y compara los feriados.','Prefira dias úteis e compare os feriados.','Choose weekdays and check holidays.'),'miniatura%20una%20zona%20para%20cada%20ritmo.jpg'],
 [tr('Ambiente de verano','Clima de verão','Summer energy'),tr('Sol, vida nocturna y movimiento.','Sol, vida noturna e movimento.','Sun, nightlife and atmosphere.'),'minitatura%20para%20experiencias%20buzios.jpg'],
 [tr('Escapada romántica','Escapada romântica','Romantic escape'),tr('Atardeceres y paseos frente al mar.','Pôr do sol e passeios à beira-mar.','Sunsets and seafront walks.'),'miniatura%20buzios%20mes%20a%20mes.jpeg']];
 const profileRecommendations=[
 tr('Para viajar con niños, prioriza playas con accesos cómodos, alojamiento bien ubicado y días sin demasiados traslados. Enero y febrero coinciden con vacaciones y más movimiento; marzo puede ser más tranquilo fuera de feriados. Antes de elegir, revisa el oleaje, servicios y accesibilidad de cada playa.','Com crianças, priorize praias com bom acesso, hospedagem bem localizada e dias sem deslocamentos demais. Janeiro e fevereiro são mais movimentados por férias; março pode ser mais calmo fora dos feriados. Confira ondas, estrutura e acessibilidade.','With children, favour accessible beaches, conveniently located accommodation and relaxed days. January and February are busy holiday months; March can be calmer outside holidays. Always check surf, facilities and access.'),
 tr('Para una experiencia más tranquila, compara marzo fuera de feriados con abril, mayo y septiembre. No hay garantía de playas vacías ni tarifas bajas: los fines de semana y eventos especiales pueden alterar el ritmo.','Para mais tranquilidade, compare março fora de feriados com abril, maio e setembro. Não há garantia de praias vazias ou tarifas baixas; fins de semana e eventos podem mudar o movimento.','For a quieter trip, compare March outside holidays with April, May and September. Empty beaches and low prices are not guaranteed: weekends and special events can change demand.'),
 tr('Diciembre, enero y febrero concentran el ambiente estival, con más movimiento, restaurantes y vida nocturna. Para Carnaval, verifica el año y las fechas oficiales: puede caer en febrero o marzo. Reserva con anticipación en períodos de alta demanda.','Dezembro, janeiro e fevereiro concentram o clima de verão, mais movimento, restaurantes e vida noturna. Confira as datas oficiais do Carnaval em cada ano: pode ser em fevereiro ou março. Reserve com antecedência.','December, January and February have the strongest summer atmosphere, lively restaurants and nightlife. Carnival dates vary by year and may fall in February or March. Book ahead during peak demand.'),
 tr('Para paseos junto al mar, atardeceres y cenas sin apuro, considera marzo, abril o mayo, comprobando pronóstico y feriados. La combinación de alojamiento cerca de Orla Bardot y una cena en el Centro puede ser más importante que elegir un mes concreto.','Para passeios à beira-mar, pôr do sol e jantares tranquilos, considere março, abril ou maio, conferindo previsão e feriados. Hospedagem perto da Orla Bardot e jantar no Centro podem importar mais que um mês específico.','For scenic walks, sunsets and unhurried dinners, consider March, April or May, checking forecasts and holidays. Staying near Orla Bardot and dining downtown can matter more than choosing a particular month.')
 ];
 const supplement=sections.slice(1).map(sec=>'<section class="bz-mm-supplement"><h2>'+esc(value(sec.title,lang))+'</h2><p>'+esc(value(sec.lead,lang))+'</p>'+sec.items.map(it=>'<article><h3>'+esc(value(it.title,lang))+'</h3><p>'+esc(value(it.text,lang))+'</p>'+bzContextPhoto(it,lang)+'</article>').join('')+'</section>').join('');
 return '<div class="bz-mm"><header class="bz-mm-hero"><div><p>'+esc(tr('GUÍA DE BÚZIOS · LAS CUATRO ESTACIONES','GUIA DE BÚZIOS · AS QUATRO ESTAÇÕES','BÚZIOS GUIDE · FOUR SEASONS'))+'</p><h1>Búzios<br><em>'+esc(tr('mes a mes','mês a mês','month by month'))+'</em></h1><p>'+esc(value(page.intro,lang))+'</p></div></header><nav id="bz-mm-selector" class="bz-mm-selector" aria-label="'+esc(tr('Elegir mes','Escolher mês','Choose a month'))+'">'+months.map(card).join('')+'</nav><div class="bz-mm-main">'+details+'</div><section class="bz-mm-travel"><h2>'+esc(tr('¿Qué mes combina con tu viaje?','Qual mês combina com sua viagem?','Which month suits your trip?'))+'</h2><p>'+esc(tr('Cada viajero vive un Búzios diferente. Encuentra tu momento ideal.','Cada viajante vive Búzios de um jeito. Descubra seu momento ideal.','Everyone experiences Búzios differently. Find your ideal time.'))+'</p><div class="bz-mm-lifestyle-grid">'+lifestyles.map((v,i)=>'<article><img alt="" loading="lazy" src="'+base+v[2]+'"><div><h3>'+esc(v[0])+'</h3><p>'+esc(v[1])+'</p><details class="bz-mm-profile-answer"><summary>'+esc(tr('VER RECOMENDACIÓN','VER RECOMENDAÇÃO','SEE RECOMMENDATION'))+' →</summary><p>'+esc(profileRecommendations[i])+'</p><a href="'+localizedHref('/destinos/buzios/guia/mes-a-mes/',lang)+'#bz-mm-selector">'+esc(tr('COMPARAR LOS 12 MESES','COMPARAR OS 12 MESES','COMPARE ALL 12 MONTHS'))+' →</a></details></div></article>').join('')+'</div></section><section class="bz-mm-extra"><details><summary>'+esc(tr('Ver guía completa, eventos y recomendaciones','Ver guia completa, eventos e recomendações','Read full guide, events and recommendations'))+'</summary>'+supplement+'<p>'+esc(value(page.notice,lang))+'</p><a href="'+localizedHref('/destinos/buzios/eventos/',lang)+'">'+esc(tr('Agenda de eventos →','Agenda de eventos →','Events calendar →'))+'</a></details></section><div class="bz-mm-cta"><h2>'+esc(tr('¿Listo para vivir Búzios en el momento perfecto?','Pronto para viver Búzios na melhor época?','Ready to experience Búzios at the right time?'))+'</h2><a href="'+localizedHref('/destinos/buzios/guia/',lang)+'">'+esc(tr('PLANIFICA TU VIAJE','PLANEJE SUA VIAGEM','PLAN YOUR TRIP'))+' →</a></div></div>';
}

function renderBuziosSoloEditorial(page,lang,sections){
 const t=(es,pt,en)=>({ES:es,PT:pt,EN:en})[lang];
 const photoRoot='https://mediumturquoise-stinkbug-270478.hostingersite.com/FOTOS/HOME/BUZIOS/';
 const soloRoot=photoRoot+'GUIA%20BUZIOS/VIAJANDO%20SOLA/';
 const uploaded=(path,name,alt)=>({src:photoRoot+path,name,alt});
 const solo={
  cover:{src:soloRoot+'1122e2c0350059b4af30dbb27835fc8b.jpg',alt:T('Viajera caminando sola por una playa rocosa de Búzios','Viajante caminhando sozinha por uma praia rochosa de Búzios','Solo traveller walking along a rocky beach in Búzios')},
  waterfront:{src:soloRoot+'669f3f69ad6e72f6c57f806d10c9393a.jpg',name:'Viajera junto al mar',alt:T('Viajera disfrutando sola de la costa de Búzios','Viajante aproveitando sozinha a costa de Búzios','Solo traveller enjoying the Búzios coastline')},
  beach:{src:soloRoot+'c82eade186edfbdb48d78228a8a925f5.jpg',name:'Viajera en una playa de Búzios',alt:T('Viajera sola junto al mar en Búzios','Viajante sozinha junto ao mar em Búzios','Solo traveller by the sea in Búzios')}
 };
 const visuals={
  '1. Elige alojamiento por la ruta completa':{src:'/assets/images/buzios/panorama-mtur.webp',name:'Paisaje de Búzios',alt:T('Paisaje costero de Búzios para ubicar la estadía','Paisagem costeira de Búzios para escolher a hospedagem','Búzios coastline for planning where to stay')},
  '2. Decide qué barrio combina con tu ritmo':uploaded('miniatura%20una%20zona%20para%20cada%20ritmo.jpg','Una zona para cada ritmo',T('Zona costera y paseo de Búzios','Região costeira e passeio de Búzios','Búzios waterfront and promenade')),
  '3. Comparte el itinerario con alguien de confianza':solo.waterfront,
  '4. Organiza llegada y primera noche':uploaded('minitatura%20llegada%20complet.jpg','Llegada a Búzios',T('Señal de Búzios en una calle del destino','Placa de Búzios em uma rua do destino','Búzios sign at a town street')),
  '5. Muévete de día con una ruta y una alternativa':buziosPhotos['Tartaruga'],
  '6. Disfruta las playas cuidando tus pertenencias':solo.beach,
  '7. Salir a cenar, tomar algo y volver':uploaded('miniatura%20comer%20pasear%20y%20volver.jpg','Centro de Búzios por la noche',T('Mesas y restaurantes en una calle concurrida de Búzios','Mesas e restaurantes em uma rua movimentada de Búzios','Restaurant tables on a lively Búzios street')),
  '8. Excursiones, barcos y buggy':uploaded('minitatura%20para%20experiencias%20buzios.jpg','Paseo de barco en grupo',T('Grupo de viajeros a bordo de un barco en Búzios','Grupo de viajantes a bordo de um barco em Búzios','Group of travellers aboard a boat in Búzios')),
  '9. Cuida de salud, descanso y presupuesto':buziosPhotos['Ferradura'],
  '10. Si algo sale mal':uploaded('minitatura%20salud%20buzios.jpg','Hospital Municipal de Búzios',T('Hospital Municipal Dr. Rodolpho Perissé en Búzios','Hospital Municipal Dr. Rodolpho Perissé em Búzios','Dr Rodolpho Perissé Municipal Hospital in Búzios')),
  '11. Socializar con calma y sin presión':uploaded('miniaturas%20actividades%20con%20salida%20local.jpg','Actividad local en Búzios',T('Actividad turística organizada con salida desde Búzios','Atividade turística organizada com saída de Búzios','Organised local activity departing from Búzios')),
  '12. Lista para el día antes de salir':uploaded('miniatura%20viaje%20sin%20sopresas.jpg','Rua das Pedras al anochecer',T('Calle empedrada de Búzios para planificar el paseo','Rua de pedras de Búzios para planejar o passeio','Búzios cobbled street for planning an evening out')),
  '01 · Tu primera caminata por Búzios':buziosPhotos['Orla Bardot'],
  '02 · Conversar, conocer gente o disfrutar del silencio':buziosPhotos['Porto da Barra'],
  '03 · Playas y paisajes sin correr':buziosPhotos['Ferradurinha'],
  'Una base práctica y un plan flexible':buziosPhotos['Paisaje de Búzios']
 };
 const photoFor=(it)=>{
  const title=value(it.title,'ES');
  if(Object.prototype.hasOwnProperty.call(visuals,title))return visuals[title];
  const declared=it.photo&&typeof it.photo==='object'&&it.photo.src?it.photo:buziosPhotoFor(it.photo);
  return declared&&declared.src?declared:null;
 };
 const chapters=sections.map((section,si)=>{
   const items=section.items.map((it,j)=>{
     const title=value(it.title,lang),photo=photoFor(it);
     const alt=photo?(photo.alt?value(photo.alt,lang):(photo.name?photo.name+' · Búzios':title)):title;
     const image=photo?'<figure class="bz-solo-story-photo"><img src="'+esc(photo.src)+'" loading="lazy" alt="'+esc(alt)+'"></figure>':'';
     return '<article class="bz-solo-story" id="bz-solo-story-'+si+'-'+j+'"><div class="bz-solo-story-copy"><span class="bz-solo-eyebrow">'+String(si+1).padStart(2,'0')+' / '+String(j+1).padStart(2,'0')+'</span><h3>'+esc(title)+'</h3><p>'+esc(value(it.text,lang))+'</p></div>'+image+'</article>';
   }).join('');
   return '<section class="bz-solo-chapter" id="bz-solo-chapter-'+si+'"><div class="bz-solo-chapter-intro"><span class="bz-solo-eyebrow">'+String(si+1).padStart(2,'0')+' / '+esc(t('GUÍA INDEPENDIENTE','GUIA INDEPENDENTE','INDEPENDENT GUIDE'))+'</span><h2>'+esc(value(section.title,lang))+'</h2><p>'+esc(value(section.lead,lang))+'</p></div>'+items+'</section>';
 }).join('');
 const nav=sections.map((sec,i)=>'<a href="#bz-solo-chapter-'+i+'"><span>'+String(i+1).padStart(2,'0')+'</span>'+esc(value(sec.title,lang))+'</a>').join('');
 return '<div class="bz-solo"><div class="bz-solo-wrap"><div class="bz-solo-topline">'+esc(t('GUÍA PRÁCTICA · BÚZIOS','GUIA PRÁTICO · BÚZIOS','PRACTICAL GUIDE · BÚZIOS'))+'</div><figure class="bz-solo-cover"><img src="'+esc(solo.cover.src)+'" alt="'+esc(value(solo.cover.alt,lang))+'"></figure><header class="bz-solo-heading"><span class="bz-solo-eyebrow">01 / '+esc(t('VIAJE INDEPENDIENTE','VIAGEM INDEPENDENTE','SOLO TRAVEL'))+'</span><h1>'+esc(t('Viajar solo. Vivir Búzios a tu ritmo.','Viajar só. Viver Búzios no seu ritmo.','Travel solo. Discover Búzios your way.'))+'</h1><p>'+esc(value(page.intro,lang))+'</p></header><nav class="bz-solo-nav" aria-label="'+esc(t('Secciones de esta guía','Seções deste guia','Guide sections'))+'">'+nav+'</nav><aside class="bz-solo-ernestinho"><span>✦ '+esc(t('DATO DE ERNESTINHO','DICA DO ERNESTINHO','ERNESTINHO’S TIP'))+'</span><p>'+esc(t('Si viajas sin compañía, vale mucho poder regresar caminando a tu alojamiento después de cenar. Compara ubicación, luz, pendientes y accesos antes que una tarifa que parece muy económica.','Viajando por conta própria, poder voltar a pé após o jantar faz diferença. Compare localização, iluminação, ladeiras e acesso antes de escolher só pela tarifa.','When travelling solo, being able to walk back after dinner matters. Compare location, lighting, hills and access rather than choosing on price alone.'))+'</p></aside>'+chapters+'<section class="bz-solo-finish"><span class="bz-solo-eyebrow">'+esc(t('TU VIAJE · TUS TIEMPOS','SUA VIAGEM · SEU RITMO','YOUR TRIP · YOUR PACE'))+'</span><h2>'+esc(t('No necesitas compañía para vivir momentos inolvidables.','Você não precisa de companhia para viver momentos inesquecíveis.','You do not need company to make unforgettable memories.'))+'</h2><p>'+esc(value(page.notice,lang))+'</p><a href="'+localizedHref('/destinos/buzios/guia/',lang)+'">'+esc(t('Explorar la guía de Búzios →','Explorar o guia de Búzios →','Explore the Búzios guide →'))+'</a></section></div></div>';
}
function renderRioStyle(page,path,lang){
 if(path.endsWith('/viajar-solo/'))return renderBuziosSoloEditorial(page,lang,(page.sections||[]).filter(x=>x.items&&x.items.length));
 const title=value(page.title,lang),sections=(page.sections||[]).filter(s=>s.items&&s.items.length);
 if(path.endsWith('/mes-a-mes/')){ return renderBuziosMonthEditorial(page,lang,sections);
  const months=sections[0]?.items||[],names=['☀️','🎭','🌊','🍂','🌤️','⛵','🏖️','🌬️','🌱','🎶','🌅','✨'];
  const tabs=[T('Mes a mes','Mês a mês','Month by month'),T('Lluvia','Chuva','Rain'),T('Calor','Calor','Heat')];
  let cards=months.map((it,i)=>'<article class="bz-month-card" data-rain="'+(i<3||i>9?'1':'0')+'" data-heat="'+(i<3||i>10?'1':'0')+'"><span>'+names[i]+'</span><small>'+String(i+1).padStart(2,'0')+' · BÚZIOS</small><h2>'+esc(value(it.title,lang))+'</h2><p>'+esc(value(it.text,lang))+'</p><h3>'+esc(T('Playa y mar','Praia e mar','Beach and sea')[lang])+'</h3><p>'+esc(T('Elige por el viento, oleaje y acceso de ese día. Geribá suele ser más abierta; Ferradura forma una bahía amplia; playas pequeñas pueden llenarse pronto. Comprueba condiciones y transporte antes de salir.','Escolha conforme vento, ondas e acesso do dia. Geribá costuma ser mais aberta; Ferradura forma uma enseada ampla; praias menores podem encher cedo. Confira condições e transporte.','Choose for the day’s wind, waves and access. Geribá is often more exposed; Ferradura is a broad bay; smaller beaches can fill early. Check conditions and transport before leaving.')[lang])+'</p><h3>'+esc(T('Movimiento, eventos y precios','Movimento, eventos e preços','Crowds, events and prices')[lang])+'</h3><p>'+esc(T('Compara días laborables, fines de semana y feriados. Solicita el precio total y revisa la agenda oficial vigente: los eventos cambian de fecha y no se repiten necesariamente cada año. En temporada alta reserva alojamiento y transporte de vuelta.','Compare dias úteis, fins de semana e feriados. Peça o preço total e confira a agenda oficial: eventos mudam e não se repetem necessariamente todo ano. Na alta temporada, reserve hospedagem e volta.','Compare weekdays, weekends and holidays. Ask for total prices and check the current official calendar: event dates change and do not necessarily repeat every year. Book accommodation and return transport during peak season.')[lang])+'</p><h3>'+esc(T('Mi lectura de Ernestinho','Minha leitura do Ernestinho','Ernestinho’s take')[lang])+'</h3><p>'+esc(T('Deja un hueco en el día. Una mañana de playa, una comida sin apuro y una tarde abierta suelen funcionar mejor que correr para marcar todos los puntos. Consulta el pronóstico de tu semana y confirma cualquier paseo de mar directamente con el operador.','Deixe espaço no dia. Uma manhã de praia, uma refeição tranquila e uma tarde livre funcionam melhor do que correr para ver tudo. Confira a previsão da semana e confirme passeios de mar com o operador.','Leave space in your day. A beach morning, an unhurried meal and a free afternoon often work better than rushing to tick every box. Check your week’s forecast and confirm boat trips with the operator.')[lang])+'</p></article>').join('');
  let out='<div class="bz-rio-structured bz-month-page"><div class="bz-wrap ec-rio-breadcrumb"><a href="'+localizedHref('/destinos/buzios/guia/',lang)+'">'+esc(T('← Guía de Búzios','← Guia de Búzios','← Búzios guide')[lang])+'</a></div><article class="ec-rio-guide"><p class="kicker">'+esc(value(page.eyebrow,lang))+'</p><h1>'+esc(title)+'</h1><p class="intro">'+esc(value(page.intro,lang))+'</p>'+'<div class="bz-month-tabs">'+tabs.map((t,i)=>'<button type="button" aria-pressed="'+(i===0?'true':'false')+'" data-filter="'+i+'">'+esc(t[lang])+'</button>').join('')+'</div><div class="bz-month-grid">'+cards+'</div>'+sections.slice(1).map((sec,si)=>'<section class="ec-rio-section"><p class="ec-rio-kicker">'+String(si+1).padStart(2,'0')+'</p><h2>'+esc(value(sec.title,lang))+'</h2><p class="ec-rio-lead">'+esc(value(sec.lead,lang))+'</p>'+sec.items.map(it=>'<article class="ec-rio-item"><h3>'+esc(value(it.title,lang))+'</h3><p>'+esc(value(it.text,lang))+'</p>'+bzContextPhoto(it,lang)+'</article>').join('')+'</section>').join('')+'<section class="ec-rio-section"><h2>'+esc(T('Antes de elegir tus fechas','Antes de escolher as datas','Before choosing your dates')[lang])+'</h2><p class="ec-rio-lead">'+esc(value(page.notice,lang))+'</p><p class="ec-rio-lead">'+esc(T('Si viajas por un festival, una fiesta local o un fin de semana largo, consulta primero la agenda de Eventos en Búzios y confirma fecha, lugar, entradas y transporte. El calendario de una edición anterior no garantiza que se repita.','Se viajar para festival ou feriado, consulte primeiro a agenda de Eventos em Búzios e confirme data, local, ingresso e transporte. Uma edição anterior não garante repetição.','If travelling for a festival or long weekend, check the Búzios Events calendar first and confirm date, venue, tickets and transport. A previous edition does not guarantee a repeat.')[lang])+'</p><a href="'+localizedHref('/destinos/buzios/eventos/',lang)+'">'+esc(T('Ver agenda de eventos →','Ver agenda de eventos →','See the events calendar →')[lang])+'</a></section></article></div>';
  return out;
 }
 let out='<div class="bz-rio-structured"><article class="ec-rio-guide"><p class="kicker">'+esc(value(page.eyebrow,lang))+'</p><h1>'+esc(title)+'</h1><p class="intro">'+esc(value(page.intro,lang))+'</p><aside class="tip"><b>'+esc(T('Consejo de Ernestinho','Dica do Ernestinho','Ernestinho’s tip')[lang])+'</b><p>'+esc((path.endsWith('/viajar-solo/')?T('Elige una base práctica, guarda cómo llegar y volver, y deja espacio para cambiar de plan. En Búzios, una buena jornada también puede ser una playa por la mañana y una cena tranquila en el Centro.','Escolha uma base prática, salve como chegar e voltar e deixe espaço para mudar de plano. Em Búzios, um bom dia também pode ser uma praia pela manhã e um jantar tranquilo no Centro.','Choose a practical base, save how to get there and back, and leave room to change plans. In Búzios, a great day can be a beach in the morning and a relaxed dinner downtown.'):T('No te quedes solo con la palabra “accesible”: pide medidas, fotos y detalles de cada tramo para la fecha de tu viaje.','Não fique apenas com a palavra “acessível”: peça medidas, fotos e detalhes de cada trecho para a data da viagem.','Do not rely on the word “accessible”: ask for measurements, photos and details for every leg on your travel dates.'))[lang])+'</p></aside>';
 const hero=page.heroPhoto;if(hero&&/GUIA%20BUZIOS/i.test(hero.src||'')&&!path.endsWith('/accesibilidad/'))out+=photoFigure(hero,lang,false);
 let n=0;sections.forEach((section,si)=>{out+='<section class="ec-rio-section"><p class="ec-rio-kicker">'+String(si+1).padStart(2,'0')+'</p><h2>'+esc(value(section.title,lang))+'</h2><p class="ec-rio-lead">'+esc(value(section.lead,lang))+'</p>';
 section.items.forEach(it=>{n++;out+='<article class="ec-rio-item"><span class="ec-rio-number">'+String(n).padStart(2,'0')+'</span><h3>'+esc(value(it.title,lang))+'</h3><p>'+esc(value(it.text,lang))+'</p>'+editorialDetails(it,lang)+bzContextPhoto(it,lang)+'</article>';});out+='</section>';});
 if(path.endsWith('/accesibilidad/')&&page.notice)out+='<aside class="tip"><b>'+esc(T('Dato de Ernestinho','Dica do Ernestinho','Ernestinho’s tip')[lang])+'</b><p>'+esc(value(page.notice,lang))+'</p></aside>';out+='<div class="ec-rio-links"><a href="'+esc(localizedHref('/destinos/buzios/guia/',lang))+'">'+esc(T('← Volver a la Guía de Búzios','← Voltar ao Guia de Búzios','← Back to Búzios guide')[lang])+'</a></div></article></div>';return out;
}

